<script setup>
import {ref,onMounted,computed} from 'vue'
import AdminOverview from './AdminOverview.vue'
import CopyButton from './CopyButton.vue'
import LocalNotices from './LocalNotices.vue'
import {api} from '../api/library.js'
const section=ref('用户'),rows=ref([]),page=ref(1),total=ref(0),term=ref(''),applied=ref(''),name=ref(''),pass=ref(''),quota=ref(0),busy=ref(false),msg=ref(''),creating=ref(false),editing=ref(null),delta=ref(1)
const pages=computed(()=>Math.max(1,Math.ceil(total.value/10)))
async function load(n=1,q=applied.value){const d=await api(`/admin/users?${new URLSearchParams({q,page:n,per_page:10})}`);rows.value=d.users;total.value=d.total;page.value=d.page;applied.value=q;editing.value=null}
async function act(fn){if(busy.value)return;busy.value=true;msg.value='';try{await fn()}catch(e){msg.value=e.message}finally{busy.value=false}}
onMounted(()=>act(()=>load()))
function generate(){const a=crypto.getRandomValues(new Uint8Array(16));const hex=v=>v.toString(16).padStart(2,'0');name.value='reader'+Array.from(a.slice(0,4),hex).join('');pass.value=Array.from(a.slice(4),hex).join('')}
function resetCreate(){creating.value=false;pass.value='';name.value='';quota.value=0}
async function create(){const who=name.value.trim();await api('/admin/users',{username:who,password:pass.value,quota:quota.value});resetCreate();term.value=who;await load(1,who);msg.value=`已创建用户「${who}」。`}
function edit(u){editing.value=editing.value===u.id?null:u.id;delta.value=1;msg.value=''}
async function adjust(u){if(!Number.isSafeInteger(delta.value)||!delta.value){msg.value='请输入非零整数，减少次数请填负数。';return}const d=await api(`/admin/users/${u.id}/quota`,{delta:delta.value});u.download_quota=d.quota;editing.value=null;msg.value=`「${u.username}」剩余 ${d.quota} 次。`}
async function modify(u,action){const word={disable:'停用',enable:'启用',delete:'删除'}[action];const detail={disable:'该用户会退出登录。',enable:'该用户可再次登录。',delete:'该账户及其下载记录将被删除，无法撤销。'}[action];if(!window.confirm(`${word}「${u.username}」？${detail}`))return;await api(`/admin/users/${u.id}${action==='delete'?'':'/'+action}`,action==='delete'?undefined:{},action==='delete'?'DELETE':'POST');await load(page.value);msg.value=`已${word}「${u.username}」。`}
function switchSection(s){resetCreate();editing.value=null;msg.value='';section.value=s}
</script>
<template><section class="desk appear"><h1>管理工作台</h1><div class="sections" role="group" aria-label="管理分区"><button v-for="s in ['用户','统计','公告']" :key="s" :aria-pressed="section===s" :disabled="busy" @click="switchSection(s)">{{s}}</button></div>
<template v-if="section==='用户'"><div class="heading"><h2>用户列表 <small>{{total}} 人</small></h2><button :disabled="busy" :aria-expanded="creating" @click="creating?resetCreate():(creating=true)">{{creating?'取消创建':'新建用户'}}</button></div>
<form v-if="creating" class="stack create" @submit.prevent="act(create)"><label>用户名<input v-model="name" required autocomplete="off"></label><label>初始密码<input v-model="pass" type="password" minlength="6" required autocomplete="new-password"></label><label>初始下载次数<input v-model.number="quota" type="number" min="0" required></label><div class="row"><button type="button" :disabled="busy" @click="generate">随机生成账号密码</button><CopyButton v-if="name&&pass" :text="`用户名：${name}\n密码：${pass}`" label="复制账号密码"/><button class="primary" :disabled="busy">创建用户</button></div></form>
<form class="searchbox" @submit.prevent="act(()=>load(1,term.trim()))"><input type="search" enterkeyhint="search" aria-label="按用户名查找" placeholder="按用户名查找" v-model="term"><button :disabled="busy">搜索</button></form>
<p v-if="!rows.length" class="empty">{{busy?'正在读取用户…':msg?'':'没有匹配的用户。'}}</p>
<article class="reader" v-for="u in rows" :key="u.id"><div class="identity"><h3>{{u.username}}</h3><small>{{u.is_admin?'管理员':u.is_disabled?'已停用':'正常'}}</small></div><div class="balance">{{u.is_admin?'不限次数':`剩余 ${u.download_quota} 次`}}<small>已下载 {{u.download_count}} 本</small></div><button v-if="!u.is_admin" class="quiet" :disabled="busy" :aria-expanded="editing===u.id" @click="edit(u)">{{editing===u.id?'收起':'管理用户'}}</button>
<div v-if="editing===u.id" class="edit"><form class="row" @submit.prevent="act(()=>adjust(u))"><label>调整次数 <input v-model.number="delta" type="number" required step="1" aria-label="调整次数"></label><button class="primary" :disabled="busy">保存次数</button></form><small>增加填正数，减少填负数。</small><div class="row secondary"><button :disabled="busy" @click="act(()=>modify(u,u.is_disabled?'enable':'disable'))">{{u.is_disabled?'启用':'停用'}}</button><button class="quiet" :disabled="busy" @click="act(()=>modify(u,'delete'))">删除用户</button></div></div></article>
<div class="pager" v-if="pages>1"><button :disabled="busy||page===1" @click="act(()=>load(page-1))">上一页</button><span>第 {{page}} / {{pages}} 页</span><button :disabled="busy||page>=pages" @click="act(()=>load(page+1))">下一页</button></div></template>
<template v-else-if="section==='统计'"><AdminOverview/><div class="export"><button disabled>导出数据库</button><small> 当前服务未提供导出接口</small></div></template><LocalNotices v-else editor/><p v-if="msg" class="notice" role="status">{{msg}}</p></section></template>
<style scoped>
.desk{max-width:680px;margin:auto}.desk h1{margin-bottom:6px}.sections,.heading,.identity,.pager{display:flex;align-items:center}.sections{border-bottom:1px solid var(--line);gap:14px}.sections button{min-width:48px;border:0;border-radius:0;background:none;color:var(--muted);padding:0 5px}.sections [aria-pressed=true]{box-shadow:inset 0 -2px var(--accent);color:var(--accent);font-weight:600}.heading,.pager{justify-content:space-between;gap:10px;margin:16px 0 8px}.heading h2,.identity h3{margin:0}.create,.edit{background:var(--surface);padding:12px;margin-bottom:10px}.reader{display:grid;grid-template-columns:minmax(0,1fr) auto 76px;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding:9px 0}.identity{align-items:start;flex-direction:column;gap:2px;overflow-wrap:anywhere}.identity h3{font-family:var(--serif);max-width:100%}.balance{text-align:right;font-variant-numeric:tabular-nums}.balance small{display:block}.edit{grid-column:1/-1;margin:0}.edit input{width:6em;min-height:44px;background:var(--bg);border:1px solid var(--line);border-radius:4px;padding:5px}.secondary{border-top:1px solid var(--line);margin-top:8px;padding-top:8px}.export{border-top:1px solid var(--line);margin-top:16px;padding-top:12px}.pager span{color:var(--muted);font-size:13px}@media(max-width:420px){.reader{grid-template-columns:minmax(0,1fr) auto 64px;gap:6px}.reader>.quiet{padding-inline:3px}.create input,.edit input{font-size:16px}}
</style>
